// Content models parsed from assets/data/content.json (generated by scripts/generate-content.ts).

List<String> _strings(dynamic v) =>
    (v as List? ?? const []).map((e) => e.toString()).toList();

class SessionItem {
  final String e;
  final int s;

  /// Lesson phase label ("Warm-up", "New today", …) — authored courses only.
  final String? p;
  const SessionItem(this.e, this.s, [this.p]);
  factory SessionItem.fromJson(Map<String, dynamic> j) =>
      SessionItem(j['e'] as String, (j['s'] as num).toInt(), j['p'] as String?);
}

List<SessionItem> _items(dynamic v) => (v as List)
    .map((e) => SessionItem.fromJson(e as Map<String, dynamic>))
    .toList();

class Exercise {
  final String id,
      name,
      category,
      kind,
      image,
      level,
      equipment,
      description,
      breath,
      cue;
  final int durationSec;
  final double kcalPerMin;
  final List<String> focus, steps, benefits;

  /// Optional licensed media (video loop / narrated guidance). Empty until provided.
  final String? video, audio;

  /// Key of our bundled demo film (`assets/video/<demo>.mp4`), or null.
  final String? demo;
  final String? tip;

  /// Classical Sanskrit name (e.g. Vrksasana), when the pose has one.
  final String? sanskrit;
  bool get isAffirmation => kind == 'affirmation';

  /// Display name without the side suffix ("Tree Pose · Right" → "Tree Pose").
  String get baseName => name.split(' · ').first;

  /// Looping demo film: licensed network media first, then our bundled demo asset.
  ({String src, bool asset})? get film => video != null
      ? (src: video!, asset: false)
      : (demo != null ? (src: 'assets/video/$demo.mp4', asset: true) : null);
  Exercise.fromJson(Map<String, dynamic> j)
    : id = j['id'],
      name = j['name'],
      category = j['category'],
      kind = j['kind'] ?? 'move',
      video = (j['media'] as Map?)?['video'] as String?,
      audio = (j['media'] as Map?)?['audio'] as String?,
      demo = j['demo'] as String?,
      tip = j['tip'] as String?,
      sanskrit = j['sanskrit'] as String?,
      image = j['image'],
      level = j['level'],
      equipment = j['equipment'],
      description = j['description'],
      breath = j['breath'],
      cue = j['cue'],
      durationSec = (j['durationSec'] as num).toInt(),
      kcalPerMin = (j['kcalPerMin'] as num).toDouble(),
      focus = _strings(j['focus']),
      steps = _strings(j['steps']),
      benefits = _strings(j['benefits']);
}

class Category {
  final String id, name, tagline, description, image;
  final List<String> exerciseIds;
  final int signatureMinutes;
  final List<SessionItem> items;
  final int kcal;
  Category.fromJson(Map<String, dynamic> j)
    : id = j['id'],
      name = j['name'],
      tagline = j['tagline'],
      description = j['description'],
      image = j['image'],
      exerciseIds = _strings(j['exerciseIds']),
      signatureMinutes = (j['signatureMinutes'] as num).toInt(),
      items = _items(j['session']['items']),
      kcal = (j['session']['kcal'] as num).toInt();
}

