class Meditation {
  final String id, title, subtitle, category, image, track, theme;

  /// Two-sentence description shown on cards and the player.
  final String about;
  final int minutes;
  final bool premium;
  final List<int>? breath;
  final List<ScriptLine> script;
  Meditation.fromJson(Map<String, dynamic> j)
    : id = j['id'],
      title = j['title'],
      subtitle = j['subtitle'],
      category = j['category'],
      image = j['image'],
      track = j['track'],
      theme = j['theme'],
      about = j['about'] as String? ?? '',
      minutes = (j['minutes'] as num).toInt(),
      premium = j['premium'] as bool,
      breath = j['breath'] == null
          ? null
          : (j['breath'] as List).map((e) => (e as num).toInt()).toList(),
      script = (j['script'] as List)
          .map((e) => ScriptLine.fromJson(e as Map<String, dynamic>))
          .toList();
}

